// Message du chat -> message à traiter (taille bornée ; n° de commande et e-mail saisis gardés à part).
const b = $json.body || {};
const email = String(b.email || '').trim().toLowerCase();
return {
  json: {
    canal: 'chat',
    texte: String(b.message || '').slice(0, 2000),
    de_email: email,
    de_nom: '',
    sujet: 'Chat du site',
    message_id: 'chat-' + Date.now().toString(36),
    recu_le: DateTime.now().setZone('Europe/Paris').toISO({ suppressMilliseconds: true }),
    entetes: {},
    chat: { numero_commande: String(b.numero_commande || '').slice(0, 20), email },
  },
};

const r = $input.first().json;
return [{ json: {
  reponse: r.reponse_chat || "Merci, votre demande est transmise à notre service client : vous recevrez une réponse par e-mail.",
  statut: r.statut || 'à traiter',
} }];
